SELECT video_id
FROM comment
WHERE comment_id = #{commentId}

SELECT c.comment_id AS commentId, c.parent_id AS parentId, c.user_id AS userId, c.content AS content, u.nickname AS nickname, c.created_at AS createdAt, c.is_deleted AS isDeleted FROM comment c JOIN users u ON c.user_id =u.user_id WHERE c.parent_id IN
#{id}
ORDER BY c.created_at
